using System.Net.Http.Headers; using System.Net.Http.Json; using Microsoft.AspNetCore.Mvc; using RaceDay.Web.Models; using RaceDay.Web.Services; namespace RaceDay.Web.Controllers; public class ProfileController(ApiClient api):Controller{[HttpGet]public async Task<IActionResult> Index(){var u=await api.Get<UserModel>("api/profile");return u is null?RedirectToAction("Login","Account"):View(new ProfileForm{FullName=u.FullName,Phone=u.Phone});}[HttpPost]public async Task<IActionResult> Index(ProfileForm f){var r=await api.Raw(HttpMethod.Put,"api/profile",JsonContent.Create(new{f.FullName,f.Phone}));if(f.Picture is not null){using var c=new MultipartFormDataContent();var sc=new StreamContent(f.Picture.OpenReadStream());sc.Headers.ContentType=new MediaTypeHeaderValue(f.Picture.ContentType);c.Add(sc,"file",f.Picture.FileName);await api.Raw(HttpMethod.Post,"api/profile/image",c);}return RedirectToAction(nameof(Index));}}
